mapper.select:
SELECT period AS "period", SUM(amount) AS "amount", SUM(cost) AS "cost", SUM(profit) AS "profit", SUM(qty) AS "qty"
FROM bi_fact_sales
WHERE period >= #{fromPeriod}
AND category = #{category}
GROUP BY period
ORDER BY period

choose.when:
SELECT COUNT(*) FROM pm_task t JOIN pm_project p ON p.id = t.project_id
WHERE p.status = 'ACTIVE' AND t.status <> 'DONE' AND t.plan_end < #{today}
  AND NOT EXISTS (SELECT 1 FROM pm_task s WHERE s.parent_id = t.id)
